export function evaluate({ inputs, time }) {
  const v0 = Number(inputs.launchSpeed) || 4.0;
  const g = 9.8;
  const apexTime = v0 / g;
  const apexHeight = (v0 * v0) / (2 * g);
  const t = Math.min(Math.max(time, 0), 2 * apexTime);
  const velocity = v0 - g * t;
  const height = Math.max(0, v0 * t - 0.5 * g * t * t);
  let mState = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    mState = "Still for an instant";
  } else if (velocity < 0) {
    mState = "Moving down";
  }
  const gState = "Gravity pulls down";
  const xCenter = 360;
  const yGround = 360;
  const pxPerMeter = 180;
  const ballY = yGround - height * pxPerMeter;
  const ballRadius = 15;
  const frameObjects = [];
  frameObjects.push({
    kind: "line",
    id: "axis.h_line",
    from: { x: 120, y: yGround },
    to: { x: 500, y: yGround },
    role: "neutral"
  });
  frameObjects.push({
    kind: "line",
    id: "axis.guide",
    from: { x: xCenter - 80, y: yGround },
    to: { x: xCenter + 80, y: yGround },
    role: "input",
    opacity: 0.6
  });
  frameObjects.push({
    kind: "text",
    id: "axis.guide_label",
    x: xCenter + 90,
    y: yGround + 4,
    text: "Launch height",
    align: "start",
    role: "neutral"
  });
  const ticks = [0, 0.5, 1.0, 1.5];
  for (let i = 0; i < ticks.length; i++) {
    const hVal = ticks[i];
    const yPos = yGround - hVal * pxPerMeter;
    frameObjects.push({
      kind: "line",
      id: "tick_line_" + i,
      from: { x: 180, y: yPos },
      to: { x: 200, y: yPos },
      role: "neutral"
    });
    frameObjects.push({
      kind: "text",
      id: "tick_text_" + i,
      x: 170,
      y: yPos + 4,
      text: hVal.toFixed(1) + "m",
      align: "end",
      role: "neutral"
    });
  }
  frameObjects.push({
    kind: "line",
    id: "tick_axis",
    from: { x: 190, y: yGround },
    to: { x: 190, y: yGround - 1.6 * pxPerMeter },
    role: "neutral"
  });
  frameObjects.push(sdk.circle("ball.toss", xCenter, ballY, ballRadius * 2, { role: "learner" }));
  const vVec = sdk.vector("vec.v", { x: xCenter - 30, y: ballY }, {
    value: velocity,
    direction: "up",
    scale: 15,
    label: "v",
    role: "output"
  });
  for (let i = 0; i < vVec.length; i++) frameObjects.push(vVec[i]);
  const aVec = sdk.vector("vec.a", { x: xCenter + 30, y: ballY }, {
    value: -g,
    direction: "up",
    scale: 6,
    label: "a",
    role: "warning"
  });
  for (let i = 0; i < aVec.length; i++) frameObjects.push(aVec[i]);
  const calloutObjs = sdk.callout(xCenter + 75, ballY - 20, [mState, gState], {
    id: "callout.toss",
    role: "neutral"
  });
  for (let i = 0; i < calloutObjs.length; i++) frameObjects.push(calloutObjs[i]);
  return {
    frame: sdk.frame(frameObjects, {
      readouts: [
        { id: "motionState", value: mState },
        { id: "gravityState", value: gState }
      ]
    }),
    quantities: {
      launchSpeed: v0,
      gravity: g,
      apexTime: apexTime,
      apexHeight: apexHeight,
      velocity: velocity,
      height: height
    }
  };
}
